-- 289_seed_machine_translations_sept4.sql
--
-- Machine-translated proposal seeds (es/ru/uk/sv) for the 49 strings the
-- Sept 4 batch (Spirit's charts) added. Same contract as 184/189/213/223/239/243/249/256/265:
-- PENDING proposals only, sentinel proposer 'claude-mt', license_assent TRUE at
-- the machine-translation terms revision. The same 196 translations ship
-- BUNDLED in I18nCatalogues.cs, so the client renders them without approval;
-- these proposals exist so human translators can see/refine them through the
-- portal (an approval overrides the bundled value via the pack overlay).
--
-- key_id = sha1("client" || chr(0) || source)[:16] — the NUL-separator form
-- tools/i18n_sync_keys.py uses.
--
-- ORDERING: seeds only keys already present in i18n_keys. Run order:
-- deploy API -> apply 288 (or run tools/i18n_sync_keys.py) -> apply this
-- file. On an unsynced database the assertion below RAISEs and the transaction
-- rolls back; re-run after the keys land. Explicit BEGIN/COMMIT (#340); every
-- statement is idempotent under the wrapper's || re-run (#243).
BEGIN;

CREATE TEMP TABLE _seed289 (
  key_id      VARCHAR(16) NOT NULL,
  lang        VARCHAR(8)  NOT NULL,
  source_hash VARCHAR(40) NOT NULL,
  target      TEXT        NOT NULL
) ON COMMIT DROP;

INSERT INTO _seed289 (key_id, lang, source_hash, target) VALUES
  -- "Deal Conditional damage"
    ('00cf7aaf51815456', 'es', 'd6c04483c4b6c4688aeb80a462e1889c65799c35', E'Infligir daño Condicional')
  , ('00cf7aaf51815456', 'ru', 'd6c04483c4b6c4688aeb80a462e1889c65799c35', E'Нанести Условный урон')
  , ('00cf7aaf51815456', 'uk', 'd6c04483c4b6c4688aeb80a462e1889c65799c35', E'Завдати Умовної шкоди')
  , ('00cf7aaf51815456', 'sv', 'd6c04483c4b6c4688aeb80a462e1889c65799c35', E'Ge Villkorlig skada')
  -- "Redrawn from Spirit's diagram: Conditional damage never Refr"
  , ('03743368bfc09bcf', 'es', '17cf3ff04e9a66a27d2ad22466075f8965e34735', E'Redibujado a partir del diagrama de Spirit: el daño Condicional nunca activa Refresh dos veces seguidas.')
  , ('03743368bfc09bcf', 'ru', '17cf3ff04e9a66a27d2ad22466075f8965e34735', E'Перерисовано по схеме Spirit: Условный урон никогда не даёт Refresh два раза подряд.')
  , ('03743368bfc09bcf', 'uk', '17cf3ff04e9a66a27d2ad22466075f8965e34735', E'Перемальовано зі схеми Spirit: Умовна шкода ніколи не дає Refresh двічі поспіль.')
  , ('03743368bfc09bcf', 'sv', '17cf3ff04e9a66a27d2ad22466075f8965e34735', E'Omritad från Spirits diagram: Villkorlig skada ger aldrig Refresh två gånger i rad.')
  -- "A shot placed second: the shot Refreshes and resets the flag"
  , ('060ce37e54f9db7d', 'es', '61fc1f50fb545395d209750161092562acaa7e35', E'Un disparo en segundo lugar: el disparo activa Refresh y reinicia la bandera')
  , ('060ce37e54f9db7d', 'ru', '61fc1f50fb545395d209750161092562acaa7e35', E'Выстрел вторым: выстрел даёт Refresh и сбрасывает флаг')
  , ('060ce37e54f9db7d', 'uk', '61fc1f50fb545395d209750161092562acaa7e35', E'Постріл другим: постріл дає Refresh і скидає прапорець')
  , ('060ce37e54f9db7d', 'sv', '61fc1f50fb545395d209750161092562acaa7e35', E'Ett skott på andra plats: skottet ger Refresh och nollställer flaggan')
  -- "The gameplay ramifications are best illustrated through Sile"
  , ('09f590ed72875261', 'es', '80444cd6246036481a041786b427412a711aca7e', E'Las consecuencias jugables se ilustran mejor con Silence. Al empezar una partida, RefreshValid está en false, así que tu primer Silence no activa un Refresh. (No he podido comprobar si el booleano se reinicia entre rondas - no se reinicia al morir, al resucitar ni al elegir cartas nuevas, así que sospecho que no.) Tras tu primer Refresh fallido, RefreshValid pasa a true. Así, tu siguiente Silence activa un Refresh pero reinicia RefreshValid a false. Y así continúa en un bucle sin fin en el que uno de cada dos Silence activa un Refresh. Cada columna de abajo es una acción; la fila superior es el estado de RefreshValid ANTES de ella:')
  , ('09f590ed72875261', 'ru', '80444cd6246036481a041786b427412a711aca7e', E'Последствия для геймплея лучше всего показать на Silence. В начале игры RefreshValid равно false, поэтому ваша первая Silence не активирует Refresh. (Проверить, сбрасывается ли булево между раундами, мне не удалось - оно не сбрасывается при смерти, воскрешении и выборе новых карт, так что подозреваю, что нет.) После первого неудавшегося Refresh RefreshValid становится true. Поэтому следующая Silence активирует Refresh, но сбрасывает RefreshValid в false. Так и продолжается бесконечный цикл, в котором каждая вторая Silence даёт успешный Refresh. Каждый столбец ниже - одно действие; верхняя строка - состояние RefreshValid ДО него:')
  , ('09f590ed72875261', 'uk', '80444cd6246036481a041786b427412a711aca7e', E'Наслідки для геймплею найкраще показати на Silence. На початку гри RefreshValid дорівнює false, тому ваша перша Silence не активує Refresh. (Перевірити, чи скидається булеве між раундами, мені не вдалося - воно не скидається при смерті, воскресінні та виборі нових карт, тож підозрюю, що ні.) Після першого невдалого Refresh RefreshValid стає true. Тому наступна Silence активує Refresh, але скидає RefreshValid у false. Так і триває нескінченний цикл, у якому кожна друга Silence дає успішний Refresh. Кожен стовпець нижче - одна дія; верхній рядок - стан RefreshValid ДО неї:')
  , ('09f590ed72875261', 'sv', '80444cd6246036481a041786b427412a711aca7e', E'Konsekvenserna för spelet illustreras bäst med Silence. I början av en match är RefreshValid satt till false, så din första Silence lyckas inte utlösa ett Refresh. (Jag har inte kunnat testa om boolen nollställs mellan rundor - den nollställs inte vid död, återuppståndelse eller nya kortval, så jag misstänker att den inte gör det.) Efter ditt första misslyckade Refresh sätts RefreshValid till true. Därmed utlöser din nästa Silence ett Refresh men nollställer RefreshValid till false. Så fortsätter det i en oändlig loop där varannan Silence utlöser ett lyckat Refresh. Varje kolumn nedan är en åtgärd; översta raden är RefreshValid-tillståndet FÖRE den:')
  -- "<color=#FFD94D><b>THERE ARE NO DAMAGE TYPES</b></color>\n\nNow"
  , ('0afe97716e208ec8', 'es', 'c79e55ef850157b7d4923353bba21f93d994478e', E'<color=#FFD94D><b>NO EXISTEN LOS TIPOS DE DAÑO</b></color>\n\nAhora que entiendes esto, debo admitir que mentí por segunda vez. Te induje, te engatusé, para que creyeras que el daño Condicional y el no Condicional son dos tipos de daño distintos, asignados individualmente a ciertos ataques por los desarrolladores. Eso es incorrecto. El daño se trata igual sea cual sea su origen. En realidad no hay tipos de daño en absoluto. Entonces, ¿cómo se decide si un daño es Condicional o no? Lo decide el daño. Literalmente. La cantidad de puntos de daño que intentas infligir determina si Refresh no se activará en absoluto, se activará de forma Condicional o se activará siempre (a menos que caiga dentro de la ventana de 0,35 segundos, en cuyo caso se vuelve Condicional).\n\nLo descubrí acumulando Silence. Mientras que un Silence normal tiene un daño máximo de unos 9, acumular dos Silence puede llegar hasta 17, probablemente más. Digo ''llegar'' porque Silence inflige daño AoE: cuanto más lejos estés del objetivo, menos daño infliges. En cualquier caso: con el daño de Silence por encima de 10, se vuelve no Condicional. Acumula dos Silence y un Refresh y podrás encadenar Silence infinitamente - siempre que aciertes cada Silence en el rango de más de 10 de daño. Si caes en el rango de 5 a 10, vuelve a ser Condicional; si bajas de 5 de daño, nunca se activa ningún Refresh. Tampoco puedes encadenar Silence demasiado rápido, o se activa la ventana de 0,35 segundos y vuelve a convertir tu daño no Condicional en Condicional. (Ya ves por qué fue una pesadilla descifrar esto.)\n\nLo mágico es que este rango se aplica a todas y cada una de las fuentes de daño. Acumula suficientes Frost Slam o Shockwave y puedes producir el mismo resultado. Lo mismo vale para el daño de explosión AoE de Timed Detonation o Explosive Bullet. Las balas normales tienen un daño mínimo de 14, así que no puedes llegar a Condicional solo con reducción de daño - pero si tu oponente coge Decay, cada tick individual lleva un daño tan bajo que no recuperas ningún Refresh. O al menos no deberías: por la inconsistencia de los ticks puede que ocasionalmente consigas uno o dos, a un ritmo muy reducido. Por el contrario, acumula suficiente daño y, aunque se reparta entre ticks, seguirás teniendo suficiente para Refresh constantes. Para cartas como EMP y Bombs Away, que no pueden cambiar su daño, esta revelación no significa nada. También significa poco para Demonic Pact, Frost Slam y Shockwave, ya que la acumulación necesaria para subir su daño a la siguiente franja no es realista en una partida normal.\n\nA continuación, un diagrama de flujo con todas las posibilidades de daño:')
  , ('0afe97716e208ec8', 'ru', 'c79e55ef850157b7d4923353bba21f93d994478e', E'<color=#FFD94D><b>ТИПОВ УРОНА НЕ СУЩЕСТВУЕТ</b></color>\n\nТеперь, когда вы это поняли, должен признаться, что солгал во второй раз. Я ввёл вас в заблуждение, уговорил поверить, что Условный и не-Условный урон - два отдельных типа урона, по отдельности назначенных разработчиками определённым атакам. Это неверно. Урон обрабатывается одинаково независимо от источника. На самом деле никаких типов урона нет вообще. Так как же решается, Условный урон или нет? Это решает сам урон. Буквально. Сколько единиц урона вы пытаетесь нанести - вот что определяет, не активируется ли Refresh вовсе, активируется Условно или активируется всегда (если только урон не попадает в окно 0,35 секунды - тогда он становится Условным).\n\nЯ обнаружил это, стакая Silence. Если у обычной Silence максимальный урон около 9, то две Silence в стаке могут достигать 17, а скорее всего и больше. Я говорю «достигать», потому что Silence наносит AoE-урон: чем дальше вы от цели, тем меньше урона. Как бы то ни было: когда урон Silence выше 10, он становится не-Условным. Возьмите две Silence и Refresh - и сможете зацикливать Silence бесконечно, при условии, что каждая Silence попадает в диапазон урона выше 10. Попадёте в диапазон от 5 до 10 - урон снова станет Условным; опуститесь ниже 5 - Refresh не сработает никогда. Слишком быстро цикл Silence тоже не прокрутить, иначе срабатывает окно 0,35 секунды и снова превращает ваш не-Условный урон в Условный. (Теперь понятно, почему разбираться в этом было таким кошмаром.)\n\nСамое волшебное - этот диапазон применяется к каждому источнику урона. Настакайте достаточно Frost Slam или Shockwave - и получите тот же результат. То же верно для AoE-урона от взрыва Timed Detonation или Explosive Bullet. У обычных пуль минимальный урон 14, так что одним снижением урона до Условного не добраться - но если противник возьмёт Decay, у каждого отдельного тика настолько низкий урон, что Refresh вы не получите вовсе. По крайней мере не должны: из-за нестабильности тиков иногда может выпасть один-два, гораздо реже. И наоборот: настакайте достаточно урона - и даже разделённого между тиками хватит на постоянные Refresh. Для карт вроде EMP и Bombs Away, урон которых не меняется, это открытие ничего не значит. Мало значит оно и для Demonic Pact, Frost Slam и Shockwave: стак, нужный, чтобы поднять их урон до следующего диапазона, в обычной игре нереалистичен.\n\nНиже - блок-схема всех вариантов урона:')
  , ('0afe97716e208ec8', 'uk', 'c79e55ef850157b7d4923353bba21f93d994478e', E'<color=#FFD94D><b>ТИПІВ ШКОДИ НЕ ІСНУЄ</b></color>\n\nТепер, коли ви це зрозуміли, мушу зізнатися, що збрехав удруге. Я ввів вас в оману, умовив повірити, що Умовна й не-Умовна шкода - два окремі типи шкоди, які розробники окремо призначили певним атакам. Це неправильно. Шкода обробляється однаково незалежно від джерела. Насправді жодних типів шкоди немає взагалі. То як же вирішується, Умовна шкода чи ні? Це вирішує сама шкода. Буквально. Скільки одиниць шкоди ви намагаєтеся завдати - ось що визначає, чи Refresh не активується зовсім, чи активується Умовно, чи активується завжди (хіба що шкода потрапляє у вікно 0,35 секунди - тоді вона стає Умовною).\n\nЯ виявив це, стакаючи Silence. Якщо у звичайної Silence максимальна шкода близько 9, то дві Silence у стаку можуть сягати 17, а скоріш за все й більше. Я кажу «сягати», бо Silence завдає AoE-шкоди: що далі ви від цілі, то менше шкоди. Хай там як: коли шкода Silence вища за 10, вона стає не-Умовною. Візьміть дві Silence і Refresh - і зможете зациклювати Silence нескінченно, за умови, що кожна Silence влучає в діапазон шкоди понад 10. Потрапите в діапазон від 5 до 10 - шкода знову стане Умовною; опуститеся нижче 5 - Refresh не спрацює ніколи. Надто швидко цикл Silence теж не прокрутити, інакше спрацьовує вікно 0,35 секунди й знову перетворює вашу не-Умовну шкоду на Умовну. (Тепер зрозуміло, чому розбиратися в цьому було таким кошмаром.)\n\nНайдивовижніше - цей діапазон застосовується до кожного джерела шкоди. Настакайте досить Frost Slam або Shockwave - і отримаєте той самий результат. Те саме стосується AoE-шкоди від вибуху Timed Detonation чи Explosive Bullet. У звичайних куль мінімальна шкода 14, тож самим зниженням шкоди до Умовної не дістатися - але якщо суперник візьме Decay, кожен окремий тік несе настільки низьку шкоду, що Refresh ви не отримаєте зовсім. Принаймні не повинні: через нестабільність тіків іноді може випасти один-два, значно рідше. І навпаки: настакайте досить шкоди - і навіть розділеної між тіками вистачить на постійні Refresh. Для карт на кшталт EMP і Bombs Away, шкода яких не змінюється, це відкриття нічого не означає. Мало важить воно й для Demonic Pact, Frost Slam і Shockwave: стак, потрібний, щоб підняти їхню шкоду до наступного діапазону, у звичайній грі нереалістичний.\n\nНижче - блок-схема всіх варіантів шкоди:')
  , ('0afe97716e208ec8', 'sv', 'c79e55ef850157b7d4923353bba21f93d994478e', E'<color=#FFD94D><b>DET FINNS INGA SKADETYPER</b></color>\n\nNu när du förstår detta måste jag erkänna att jag ljög en andra gång. Jag vilseledde dig, lockade dig att tro att Villkorlig och icke-Villkorlig skada är två separata skadetyper som utvecklarna tilldelat vissa attacker var för sig. Det stämmer inte. Skada behandlas likadant oavsett källa. I själva verket finns det inga skadetyper alls. Så hur avgörs det om skada är Villkorlig eller inte? Skadan avgör det. Bokstavligen. Hur många skadepoäng du försöker ge avgör om Refresh inte aktiveras alls, aktiveras Villkorligt eller aktiveras alltid (såvida det inte landar inom 0,35-sekundersfönstret, då det blir Villkorligt).\n\nJag upptäckte detta när jag staplade Silence. Medan en vanlig Silence har en maxskada på runt 9 kan två staplade Silence nå så högt som 17, troligen mer. Jag säger ''nå'' eftersom Silence ger AoE-skada - ju längre bort du är från målet, desto mindre skada ger du. Hur som helst: med Silences skada över 10 blir den icke-Villkorlig. Stapla två Silence och ett Refresh och du kan loopa Silence i oändlighet - förutsatt att du landar varje Silence i intervallet över 10 skada. Hamnar du i intervallet 5 till 10 blir det Villkorligt igen; hamnar du under 5 skada utlöses aldrig något Refresh. Du kan inte heller cykla Silence för snabbt, annars slår 0,35-sekundersfönstret till och gör din icke-Villkorliga skada Villkorlig igen. (Förstår du varför det här var en sådan mardröm att lista ut.)\n\nDet magiska är att det här intervallet gäller varenda skadekälla. Stapla tillräckligt många Frost Slam eller Shockwave och du kan få samma resultat. Detsamma gäller AoE-explosionsskada från Timed Detonation eller Explosive Bullet. Vanliga kulor har en minimiskada på 14, så du kan inte nå Villkorlig enbart med skadereduktion - men om din motståndare får Decay bär varje enskilt tick så låg skada att du inte får några Refresh tillbaka. Eller borde åtminstone inte: på grund av tick-inkonsekvens kan du ibland få ett eller två, i kraftigt reducerad takt. Omvänt, stapla tillräckligt med skada så har du, även när den delas upp mellan ticks, fortfarande nog för ständiga Refresh. För kort som EMP och Bombs Away, som inte kan ändra sin skada, betyder den här upptäckten ingenting. Den betyder också lite för Demonic Pact, Frost Slam och Shockwave, eftersom den stapling som krävs för att lyfta deras skada till nästa band inte är realistisk i en vanlig match.\n\nNedan följer ett flödesschema över alla skademöjligheter:')
  -- "More than 10"
  , ('14a19ff455d8ab87', 'es', 'd5e82416a4a915e30ac4f2873b98cfb88c71bd55', E'Más de 10')
  , ('14a19ff455d8ab87', 'ru', 'd5e82416a4a915e30ac4f2873b98cfb88c71bd55', E'Больше 10')
  , ('14a19ff455d8ab87', 'uk', 'd5e82416a4a915e30ac4f2873b98cfb88c71bd55', E'Більше 10')
  , ('14a19ff455d8ab87', 'sv', 'd5e82416a4a915e30ac4f2873b98cfb88c71bd55', E'Mer än 10')
  -- "Bullet damage"
  , ('168a24e7a15c6676', 'es', 'a0e4252cefdd47139828d4b0e4a36f5d513a193a', E'Daño de bala')
  , ('168a24e7a15c6676', 'ru', 'a0e4252cefdd47139828d4b0e4a36f5d513a193a', E'Урон от пули')
  , ('168a24e7a15c6676', 'uk', 'a0e4252cefdd47139828d4b0e4a36f5d513a193a', E'Шкода від кулі')
  , ('168a24e7a15c6676', 'sv', 'a0e4252cefdd47139828d4b0e4a36f5d513a193a', E'Kulskada')
  -- "All of these tests were carried out in the sandbox gamemode "
  , ('1c210f8ba97a1f77', 'es', 'e358740b825518d127f9d3b4cffac22635cab524', E'Todas estas pruebas se realizaron en el modo sandbox con dos jugadores, uno con teclado y el otro con mando. Cada prueba se repitió varias veces para asegurar que los resultados fueran consistentes, o al menos consistentemente inconsistentes. No se distinguió entre el daño AoE de Timed Detonation adherido a un jugador y el adherido a una superficie.\n\nPrometedores candidatos a infligir daño, como Chilling Presence, se excluyeron tanto por no activar ninguna carta ni mejora como por no infligir daño alguno. Cada entrada de la lista inflige daño de alguna forma, y cada manera única de infligir daño tiene su entrada. Por tanto, no hay métodos para activar cartas o mejoras basadas en daño sin infligir alguna cantidad de daño. Puede parecer obvio pero, dada la rareza del resto del sistema, nunca se está del todo seguro.')
  , ('1c210f8ba97a1f77', 'ru', 'e358740b825518d127f9d3b4cffac22635cab524', E'Все эти тесты проводились в режиме песочницы с двумя игроками: один на клавиатуре, другой на контроллере. Каждый тест повторялся несколько раз, чтобы убедиться, что результаты стабильны - или хотя бы стабильно нестабильны. Различий между AoE-уроном Timed Detonation, прилипшей к игроку, и прилипшей к поверхности не делалось.\n\nМногообещающие кандидаты на нанесение урона, такие как Chilling Presence, были исключены, поскольку они не активируют ни карты, ни баффы и не наносят никакого урона. Каждая запись в списке наносит урон в той или иной форме, и у каждого уникального способа нанести урон есть запись. Таким образом, нет способов активировать карты или баффы, связанные с уроном, не нанеся хоть какой-то урон. Это может показаться очевидным, но, учитывая странность остальной системы, лишняя уверенность не помешает.')
  , ('1c210f8ba97a1f77', 'uk', 'e358740b825518d127f9d3b4cffac22635cab524', E'Усі ці тести проводилися в режимі пісочниці з двома гравцями: один на клавіатурі, другий на контролері. Кожен тест повторювався кілька разів, щоб переконатися, що результати стабільні - або принаймні стабільно нестабільні. Відмінності між AoE-шкодою Timed Detonation, що прилипла до гравця, і тією, що прилипла до поверхні, не робилося.\n\nБагатообіцяючих кандидатів на завдання шкоди, як-от Chilling Presence, було виключено, бо вони не активують ні карт, ні бафів і не завдають жодної шкоди. Кожен запис у списку завдає шкоди в тій чи іншій формі, і кожен унікальний спосіб завдати шкоди має свій запис. Отже, немає способів активувати карти чи бафи, пов''язані зі шкодою, не завдавши хоч якоїсь шкоди. Це може здаватися очевидним, але, зважаючи на дивність решти системи, зайва певність не завадить.')
  , ('1c210f8ba97a1f77', 'sv', 'e358740b825518d127f9d3b4cffac22635cab524', E'Alla dessa tester genomfördes i sandlådeläget med två spelare, en på tangentbord och den andra på handkontroll. Varje test upprepades flera gånger för att säkerställa att resultaten var konsekventa, eller åtminstone konsekvent inkonsekventa. Ingen skillnad gjordes mellan Timed Detonation-AoE-skada som fäst på en spelare och sådan som fäst på en yta.\n\nLovande potentiella skadegivare, som Chilling Presence, uteslöts eftersom de varken utlöste några kort eller buffar eller gav någon skada. Varje post i listan ger skada i någon form, och varje unikt sätt att ge skada har en post. Alltså finns det inga sätt att utlösa skadebaserade kort eller buffar utan att ge någon mängd skada. Det kan verka självklart men, med tanke på hur konstigt resten av systemet är, kan man aldrig vara riktigt säker.')
