  , ('d434848c2300cbae', 'es', '1d97ecb0b3bc6756d3846d46c2f23a482c695549', E'Poner RefreshValid en true')
  , ('d434848c2300cbae', 'ru', '1d97ecb0b3bc6756d3846d46c2f23a482c695549', E'Установить RefreshValid = true')
  , ('d434848c2300cbae', 'uk', '1d97ecb0b3bc6756d3846d46c2f23a482c695549', E'Встановити RefreshValid = true')
  , ('d434848c2300cbae', 'sv', '1d97ecb0b3bc6756d3846d46c2f23a482c695549', E'Sätt RefreshValid till true')
  -- "A quick follow-up shot (QShoot) counts as Conditional damage"
  , ('d4723ed96203417e', 'es', '9954788202428cecdadff2a0a65362345ce8612f', E'Un disparo rápido de seguimiento (QShoot) cuenta como daño Condicional')
  , ('d4723ed96203417e', 'ru', '9954788202428cecdadff2a0a65362345ce8612f', E'Быстрый повторный выстрел (QShoot) считается Условным уроном')
  , ('d4723ed96203417e', 'uk', '9954788202428cecdadff2a0a65362345ce8612f', E'Швидкий повторний постріл (QShoot) вважається Умовною шкодою')
  , ('d4723ed96203417e', 'sv', '9954788202428cecdadff2a0a65362345ce8612f', E'Ett snabbt uppföljningsskott (QShoot) räknas som Villkorlig skada')
  -- "Conditional - every other time; see RefreshValid below"
  , ('d7cf4979f9ad74e4', 'es', '696b63f21cd0801ccf923c12444a40196f9febb0', E'Condicional - una vez de cada dos; ver RefreshValid más abajo')
  , ('d7cf4979f9ad74e4', 'ru', '696b63f21cd0801ccf923c12444a40196f9febb0', E'Условный - через раз; см. RefreshValid ниже')
  , ('d7cf4979f9ad74e4', 'uk', '696b63f21cd0801ccf923c12444a40196f9febb0', E'Умовний - через раз; див. RefreshValid нижче')
  , ('d7cf4979f9ad74e4', 'sv', '696b63f21cd0801ccf923c12444a40196f9febb0', E'Villkorlig - varannan gång; se RefreshValid nedan')
  -- "Lifesteal"
  , ('d9d65e5bcdfa2dac', 'es', '57239ad99b94977b15b6bb55498ff295eb205f8a', E'Robo de vida')
  , ('d9d65e5bcdfa2dac', 'ru', '57239ad99b94977b15b6bb55498ff295eb205f8a', E'Лайфстил')
  , ('d9d65e5bcdfa2dac', 'uk', '57239ad99b94977b15b6bb55498ff295eb205f8a', E'Лайфстіл')
  , ('d9d65e5bcdfa2dac', 'sv', '57239ad99b94977b15b6bb55498ff295eb205f8a', E'Livsstöld')
  -- "Inside the 0.35 s window?"
  , ('de84355ebcd60fa2', 'es', '70f1507a50aa1affe9be3d1d4a9a831047950cd9', E'¿Dentro de la ventana de 0,35 s?')
  , ('de84355ebcd60fa2', 'ru', '70f1507a50aa1affe9be3d1d4a9a831047950cd9', E'В окне 0,35 с?')
  , ('de84355ebcd60fa2', 'uk', '70f1507a50aa1affe9be3d1d4a9a831047950cd9', E'У вікні 0,35 с?')
  , ('de84355ebcd60fa2', 'sv', '70f1507a50aa1affe9be3d1d4a9a831047950cd9', E'Inom 0,35 s-fönstret?')
  -- "That amounts to all my current understanding of Conditional "
  , ('dfab60f0e9799dbb', 'es', 'd9077ef0f07dec9c41db819f4ac30d7295177eb9', E'Eso resume todo lo que entiendo actualmente sobre el daño Condicional. Mi modelo de lo que ocurre entre bastidores es por completo una construcción (no he visto el código fuente), pero predice correctamente todo el comportamiento probado hasta ahora, y he sido minucioso. Aun así, hay límites: no sé si el booleano RefreshValid lo guarda el atacante o el objetivo - es decir, si cada jugador tiene un tope de Refresh que puede activar para sí mismo, o cada objetivo tiene un tope de Refresh que puede activar para otros. En un 1v1 no hay diferencia, pero en un FFA sí la habría. ¡Si al menos hubiera un modo de juego gratuito que pudiera usar para probar esta función!\n\n<color=#FFD94D><b>CONCLUSIÓN</b></color>\n\nAhora bien, por muy bellamente complejo que sea este sistema, tengo que preguntarme cómo demonios pensaron los desarrolladores que sería buena idea. ¿Qué se supone que equilibra? ¿Por qué la cantidad de daño dicta los Refresh? ¿Cómo iba a saber nadie nada de esto? Preguntas que solo puede responder la mente retorcida que ideó este sistema.\n\nAprecio las sutilezas del sistema, pero desde el punto de vista jugable es abominable. Ningún humano real va a calcular con precisión su estado de RefreshValid en medio de una pelea - eso si alguna vez consigues una build en la que esta información importe. Las probabilidades de que mis hallazgos afecten a tus próximas 30 partidas van de bajas a inexistentes. Al final del día, la experiencia que produce este sistema es de confusión, frustración y aleatoriedad. Y sin embargo, dicho todo esto, no querría que se cambiara. ¿Por qué? Porque si lo hicieran, la última semana de mi vida habría sido en vano.\n\nGracias por leer mis divagaciones. Espero que al menos la tabla te resulte útil.\n\n<color=#8A8A93>Lectura relacionada: <color=#7FD4FF>Bloqueo</color> explica qué hace realmente un bloqueo y qué cartas dependen de él; <color=#7FD4FF>Veneno y daño en el tiempo</color> explica cómo se aplica y sincroniza el daño por ticks.</color>')
  , ('dfab60f0e9799dbb', 'ru', 'd9077ef0f07dec9c41db819f4ac30d7295177eb9', E'Это всё, что я на данный момент понимаю об Условном уроне. Моя модель происходящего за кулисами - целиком конструкция (исходный код я не видел), но она верно предсказывает всё протестированное поведение, а тестировал я тщательно. И всё же есть пределы: я не знаю, хранится ли булево RefreshValid у атакующего или у цели - то есть у каждого ли игрока есть лимит на Refresh, которые он может активировать для себя, или у каждой цели есть лимит на Refresh, которые она может активировать для других. В 1v1 разницы нет, а в FFA была бы. Вот бы существовал какой-нибудь бесплатный режим игры, в котором это можно проверить!\n\n<color=#FFD94D><b>ВЫВОД</b></color>\n\nИ всё же, каким бы прекрасно сложным ни был этот механизм, я должен спросить: с чего разработчики решили, что это хорошая идея? Что она должна балансировать? Почему количество урона диктует Refresh? Как вообще кто-то должен был обо всём этом узнать? Вопросы, на которые способен ответить лишь тот извращённый ум, что придумал эту систему.\n\nЯ ценю тонкости системы, но с точки зрения геймплея она отвратительна. Ни один живой человек не будет точно вычислять своё состояние RefreshValid посреди боя - это если вам вообще попадётся билд, в котором эта информация имеет значение. Шансы, что мои находки повлияют на ваши следующие 30 матчей, - от низких до нулевых. В конечном счёте эта система даёт игроку ощущение путаницы, разочарования и случайности. И всё же, при всём сказанном, я не хотел бы, чтобы её меняли. Почему? Потому что тогда последняя неделя моей жизни прошла бы зря.\n\nСпасибо, что прочли мои размышления. Надеюсь, хотя бы таблица окажется полезной.\n\n<color=#8A8A93>Читайте также: <color=#7FD4FF>Блок</color> - что на самом деле делает блок и какие карты на нём завязаны; <color=#7FD4FF>Яд и урон со временем</color> - как ложится и синхронизируется периодический урон.</color>')
  , ('dfab60f0e9799dbb', 'uk', 'd9077ef0f07dec9c41db819f4ac30d7295177eb9', E'Це все, що я наразі розумію про Умовну шкоду. Моя модель того, що відбувається за лаштунками, - цілком конструкція (вихідного коду я не бачив), але вона правильно передбачає всю протестовану поведінку, а тестував я ретельно. І все ж є межі: я не знаю, чи зберігається булеве RefreshValid в атакувальника чи в цілі - тобто чи в кожного гравця є ліміт на Refresh, які він може активувати для себе, чи в кожної цілі є ліміт на Refresh, які вона може активувати для інших. У 1v1 різниці немає, а у FFA була б. От би існував якийсь безкоштовний режим гри, у якому це можна перевірити!\n\n<color=#FFD94D><b>ВИСНОВОК</b></color>\n\nІ все ж, яким би прекрасно складним не був цей механізм, я мушу запитати: з чого розробники вирішили, що це гарна ідея? Що вона має балансувати? Чому кількість шкоди диктує Refresh? Як узагалі хтось мав про все це дізнатися? Питання, на які здатен відповісти лише той викривлений розум, що вигадав цю систему.\n\nЯ ціную тонкощі системи, але з погляду геймплею вона огидна. Жодна жива людина не буде точно обчислювати свій стан RefreshValid посеред бою - це якщо вам узагалі трапиться білд, у якому ця інформація має значення. Шанси, що мої знахідки вплинуть на ваші наступні 30 матчів, - від низьких до нульових. Зрештою ця система дає гравцеві відчуття плутанини, розчарування й випадковості. І все ж, попри все сказане, я не хотів би, щоб її змінювали. Чому? Бо тоді останній тиждень мого життя минув би марно.\n\nДякую, що прочитали мої роздуми. Сподіваюся, хоча б таблиця стане в пригоді.\n\n<color=#8A8A93>Читайте також: <color=#7FD4FF>Блокування</color> - що насправді робить блок і які карти на ньому тримаються; <color=#7FD4FF>Отрута й шкода з часом</color> - як лягає й синхронізується періодична шкода.</color>')
  , ('dfab60f0e9799dbb', 'sv', 'd9077ef0f07dec9c41db819f4ac30d7295177eb9', E'Det är hela min nuvarande förståelse av Villkorlig skada. Min modell av vad som pågår bakom kulisserna är helt och hållet en konstruktion (jag har inte sett källkoden), men den förutsäger korrekt allt hittills testat beteende, och jag har varit noggrann. Ändå finns det gränser: jag vet inte om RefreshValid-boolen hålls av angriparen eller målet - det vill säga om varje spelare har ett tak för de Refresh de kan utlösa åt sig själva, eller om varje mål har ett tak för de Refresh de kan utlösa åt andra. I en 1v1 spelar det ingen roll, men i en FFA skulle det göra det. Om det bara fanns ett spelläge av typen free-to-play som jag kunde använda för att testa den här funktionen!\n\n<color=#FFD94D><b>SLUTSATS</b></color>\n\nHur vackert komplext det här systemet än är måste jag fråga hur i hela friden utvecklarna tänkte att det var en bra idé. Vad är det tänkt att balansera? Varför styr mängden skada över Refresh? Hur skulle någon kunna veta något av detta? Frågor som bara den förvridna hjärna som drömde upp systemet kan besvara.\n\nJag uppskattar systemets finesser, men ur ett spelperspektiv är det avskyvärt. Ingen verklig människa kommer att räkna ut sitt RefreshValid-tillstånd korrekt mitt i en strid - det vill säga, om du någonsin får en build där den här informationen spelar roll. Chansen att mina fynd påverkar dina nästa 30 matcher är någonstans mellan låg och obefintlig. I slutändan är spelarupplevelsen som systemet ger en av förvirring, frustration och slump. Ändå, allt detta sagt, skulle jag inte vilja att det ändrades. Varför? För om det gjordes skulle den senaste veckan av mitt liv ha varit bortkastad.\n\nTack för att du läste mina utläggningar. Jag hoppas att du åtminstone har nytta av tabellen.\n\n<color=#8A8A93>Relaterad läsning: <color=#7FD4FF>Blockering</color> tar upp vad ett block faktiskt gör och vilka kort som bygger på det; <color=#7FD4FF>Gift & skada över tid</color> tar upp hur tickskada landar och synkas.</color>')
  -- "Conditional"
  , ('ebc8ae2d4c714ddc', 'es', 'c3accb895f001e39bb983a80902ba897c94294bd', E'Condicional')
  , ('ebc8ae2d4c714ddc', 'ru', 'c3accb895f001e39bb983a80902ba897c94294bd', E'Условный')
  , ('ebc8ae2d4c714ddc', 'uk', 'c3accb895f001e39bb983a80902ba897c94294bd', E'Умовний')
  , ('ebc8ae2d4c714ddc', 'sv', 'c3accb895f001e39bb983a80902ba897c94294bd', E'Villkorlig')
  -- "QUICK SHOTS INSIDE THE 0.35 SECOND WINDOW"
  , ('efd9786032f9577c', 'es', 'b7d4d9f0f1bf5f98f36ab7bf5a6e1ac3cc32c17e', E'DISPAROS RÁPIDOS DENTRO DE LA VENTANA DE 0,35 SEGUNDOS')
  , ('efd9786032f9577c', 'ru', 'b7d4d9f0f1bf5f98f36ab7bf5a6e1ac3cc32c17e', E'БЫСТРЫЕ ВЫСТРЕЛЫ В ОКНЕ 0,35 СЕКУНДЫ')
  , ('efd9786032f9577c', 'uk', 'b7d4d9f0f1bf5f98f36ab7bf5a6e1ac3cc32c17e', E'ШВИДКІ ПОСТРІЛИ У ВІКНІ 0,35 СЕКУНДИ')
  , ('efd9786032f9577c', 'sv', 'b7d4d9f0f1bf5f98f36ab7bf5a6e1ac3cc32c17e', E'SNABBA SKOTT INOM 0,35-SEKUNDERSFÖNSTRET')
  -- "<color=#FFD94D><b>THE 0.35 SECOND WINDOW</b></color>\n\nTo pre"
  , ('f725fffe65b21b6f', 'es', '0d145cbc5195fb34ea7021bd4ccb82e1bb473306', E'<color=#FFD94D><b>LA VENTANA DE 0,35 SEGUNDOS</b></color>\n\nPara prepararte para este conocimiento, primero debo admitir que mentí en la tabla. Donde dice que el daño de bala activa un Refresh con un simple Sí, debería llevar un asterisco: lo hace la mayoría de las veces, pero no siempre. Presumiblemente para ayudar a equilibrar cartas como Burst y Spray, los desarrolladores pusieron un sistema que convierte el daño no Condicional repetido rápidamente en daño Condicional. Dispara a un oponente una vez y obtienes daño no Condicional; dispárale de nuevo dentro de una ventana de unos 0,35 segundos y ese segundo disparo es Condicional. La ventana se reinicia tras cada disparo. A continuación, los disparos secundarios (y terciarios) rápidos se indican como QShoot:')
  , ('f725fffe65b21b6f', 'ru', '0d145cbc5195fb34ea7021bd4ccb82e1bb473306', E'<color=#FFD94D><b>ОКНО В 0,35 СЕКУНДЫ</b></color>\n\nЧтобы подготовить вас к этому знанию, сначала должен признаться, что в таблице я солгал. Там, где сказано, что урон от пули активирует Refresh с простым «Да», должна стоять звёздочка: он активирует его в большинстве случаев, но не всегда. Предположительно, чтобы помочь сбалансировать карты вроде Burst и Spray, разработчики добавили систему, которая превращает быстро повторяющийся не-Условный урон в Условный. Выстрелите в противника один раз - получите не-Условный урон; выстрелите снова в окне около 0,35 секунды - и второй выстрел будет Условным. Окно сбрасывается после каждого выстрела. Ниже быстрые вторые (и третьи) выстрелы обозначены как QShoot:')
  , ('f725fffe65b21b6f', 'uk', '0d145cbc5195fb34ea7021bd4ccb82e1bb473306', E'<color=#FFD94D><b>ВІКНО У 0,35 СЕКУНДИ</b></color>\n\nЩоб підготувати вас до цього знання, спершу мушу зізнатися, що в таблиці я збрехав. Там, де сказано, що шкода від кулі активує Refresh простим «Так», має стояти зірочка: вона активує його здебільшого, але не завжди. Імовірно, щоб допомогти збалансувати карти на кшталт Burst і Spray, розробники додали систему, яка перетворює швидко повторювану не-Умовну шкоду на Умовну. Вистріліть у суперника один раз - отримаєте не-Умовну шкоду; вистріліть знову у вікні близько 0,35 секунди - і другий постріл буде Умовним. Вікно скидається після кожного пострілу. Нижче швидкі другі (і треті) постріли позначено як QShoot:')
  , ('f725fffe65b21b6f', 'sv', '0d145cbc5195fb34ea7021bd4ccb82e1bb473306', E'<color=#FFD94D><b>0,35-SEKUNDERSFÖNSTRET</b></color>\n\nFör att förbereda dig på den här kunskapen måste jag först erkänna att jag ljög i tabellen. Där det står att kulskada utlöser ett Refresh med ett rakt Ja borde det stå en asterisk: det gör det för det mesta, men inte alltid. Förmodligen för att hjälpa till att balansera kort som Burst och Spray införde utvecklarna ett system som förvandlar snabbt upprepad icke-Villkorlig skada till Villkorlig skada. Skjut en motståndare en gång och du får icke-Villkorlig skada; skjut igen inom ett fönster på ungefär 0,35 sekunder och det andra skottet är Villkorligt. Fönstret nollställs efter varje skott. Nedan betecknas snabba andra (och tredje) skott QShoot:')
  -- "TABLE OF DAMAGE INTERACTIONS"
  , ('f851a9aad9ea6141', 'es', '704ef77f6c313746fb6ba54dd99fce50481d19b1', E'TABLA DE INTERACCIONES DEL DAÑO')
  , ('f851a9aad9ea6141', 'ru', '704ef77f6c313746fb6ba54dd99fce50481d19b1', E'ТАБЛИЦА ВЗАИМОДЕЙСТВИЙ УРОНА')
  , ('f851a9aad9ea6141', 'uk', '704ef77f6c313746fb6ba54dd99fce50481d19b1', E'ТАБЛИЦЯ ВЗАЄМОДІЙ ШКОДИ')
  , ('f851a9aad9ea6141', 'sv', '704ef77f6c313746fb6ba54dd99fce50481d19b1', E'TABELL ÖVER SKADEINTERAKTIONER')
  -- "triggers"
  , ('fdf90a6e35fd8343', 'es', '0d850d1fb8c4564a96bca7874d3015c0176cbdd0', E'se activa')
  , ('fdf90a6e35fd8343', 'ru', '0d850d1fb8c4564a96bca7874d3015c0176cbdd0', E'срабатывает')
  , ('fdf90a6e35fd8343', 'uk', '0d850d1fb8c4564a96bca7874d3015c0176cbdd0', E'спрацьовує')
  , ('fdf90a6e35fd8343', 'sv', '0d850d1fb8c4564a96bca7874d3015c0176cbdd0', E'utlöses')
  -- "Reset the window"
  , ('ffe4136002328f40', 'es', '71bf6674aaabb4f9885c20f994c05de35197d594', E'Reiniciar la ventana')
  , ('ffe4136002328f40', 'ru', '71bf6674aaabb4f9885c20f994c05de35197d594', E'Сбросить окно')
  , ('ffe4136002328f40', 'uk', '71bf6674aaabb4f9885c20f994c05de35197d594', E'Скинути вікно')
  , ('ffe4136002328f40', 'sv', '71bf6674aaabb4f9885c20f994c05de35197d594', E'Nollställ fönstret');

INSERT INTO i18n_proposals
  (key_id, language_code, source_hash, proposed_target, proposer_steam_id,
   license_assent, license_terms_rev, assented_at, status, created_at)
SELECT v.key_id, v.lang, v.source_hash, v.target, 'claude-mt',
       TRUE, 'machine-v1', NOW(), 'pending', NOW()
  FROM _seed289 v
  JOIN i18n_keys k ON k.key_id = v.key_id AND k.retired_at IS NULL
                  AND k.source_hash = v.source_hash
 WHERE NOT EXISTS (
   SELECT 1 FROM i18n_proposals p
    WHERE p.key_id = v.key_id AND p.language_code = v.lang
      AND p.status = 'pending')
   AND NOT EXISTS (
   SELECT 1 FROM i18n_proposals p2
    WHERE p2.key_id = v.key_id AND p2.language_code = v.lang
      AND p2.proposer_steam_id = 'claude-mt'
      AND p2.source_hash = v.source_hash);

DO $$
DECLARE
  uncovered INTEGER;
  sample TEXT;
BEGIN
  SELECT COUNT(*) INTO uncovered
    FROM _seed289 v
   WHERE NOT EXISTS (
           SELECT 1 FROM i18n_proposals p
            WHERE p.key_id = v.key_id AND p.language_code = v.lang
              AND (p.source_hash = v.source_hash OR p.status = 'pending'))
     AND NOT EXISTS (
           SELECT 1 FROM i18n_entries e
            WHERE e.key_id = v.key_id AND e.language_code = v.lang
              AND e.state = 'approved');
  IF uncovered <> 0 THEN
    SELECT string_agg(x.key_id || '/' || x.lang, ', ')
      INTO sample
      FROM (SELECT v.key_id, v.lang FROM _seed289 v
             WHERE NOT EXISTS (
                     SELECT 1 FROM i18n_proposals p
                      WHERE p.key_id = v.key_id AND p.language_code = v.lang
                        AND (p.source_hash = v.source_hash OR p.status = 'pending'))
               AND NOT EXISTS (
                     SELECT 1 FROM i18n_entries e
                      WHERE e.key_id = v.key_id AND e.language_code = v.lang
                        AND e.state = 'approved')
             LIMIT 5) x;
    RAISE EXCEPTION 'migration 289: % of 196 seed pairs did not land (e.g. %) - the usual cause is that 288 / tools/i18n_sync_keys.py has not run against this database yet; nothing committed', uncovered, sample;
  END IF;

  RAISE NOTICE 'migration 289: all 196 seed pairs covered (49 keys x es/ru/uk/sv)';
END $$;

COMMIT;
